694	void Fetcher::downloadBaseOrProjectionPartToDisk(
695	    const String & replica_path,
696	    DataPartStorageBuilderPtr & data_part_storage_builder,
697	    bool sync,
698	    PooledReadWriteBufferFromHTTP & in,
699	    MergeTreeData::DataPart::Checksums & checksums,
700	    ThrottlerPtr throttler) const
701	{
702	    size_t files;
703	    readBinary(files, in);
704	
705	    for (size_t i = 0; i < files; ++i)
706	    {
707	        String file_name;
708	        UInt64 file_size;
709	
710	        readStringBinary(file_name, in);
711	        readBinary(file_size, in);
712	
713	        /// File must be inside "absolute_part_path" directory.
714	        /// Otherwise malicious ClickHouse replica may force us to write to arbitrary path.
715	        String absolute_file_path = fs::weakly_canonical(fs::path(data_part_storage_builder->getRelativePath()) / file_name);
716	        if (!startsWith(absolute_file_path, fs::weakly_canonical(data_part_storage_builder->getRelativePath()).string()))
717	            throw Exception(ErrorCodes::INSECURE_PATH,
718	                "File path ({}) doesn't appear to be inside part path ({}). "
719	                "This may happen if we are trying to download part from malicious replica or logical error.",
720	                absolute_file_path, data_part_storage_builder->getRelativePath());
721	
722	        auto file_out = data_part_storage_builder->writeFile(file_name, file_size, {});
723	        HashingWriteBuffer hashing_out(*file_out);
724	        copyDataWithThrottler(in, hashing_out, file_size, blocker.getCounter(), throttler);
725	
726	        if (blocker.isCancelled())
727	        {
728	            /// NOTE The is_cancelled flag also makes sense to check every time you read over the network,
729	            /// performing a poll with a not very large timeout.
730	            /// And now we check it only between read chunks (in the `copyData` function).
731	            data_part_storage_builder->removeRecursive();
732	            throw Exception("Fetching of part was cancelled", ErrorCodes::ABORTED);
733	        }
734	
735	        MergeTreeDataPartChecksum::uint128 expected_hash;
736	        readPODBinary(expected_hash, in);
737	
738	        if (expected_hash != hashing_out.getHash())
739	            throw Exception(ErrorCodes::CHECKSUM_DOESNT_MATCH,
740	                "Checksum mismatch for file {} transferred from {}",
741	                (fs::path(data_part_storage_builder->getFullPath()) / file_name).string(),
742	                replica_path);
743	
744	        if (file_name != "checksums.txt" &&
745	            file_name != "columns.txt" &&
746	            file_name != IMergeTreeDataPart::DEFAULT_COMPRESSION_CODEC_FILE_NAME)
747	            checksums.addFile(file_name, file_size, expected_hash);
748	
749	        if (sync)
750	            hashing_out.sync();
751	    }
752	}
