468	    bool operator< (const Field & rhs) const
469	    {
470	        if (which < rhs.which)
471	            return true;
472	        if (which > rhs.which)
473	            return false;
474	
475	        switch (which)
476	        {
477	            case Types::Null:    return false;
478	            case Types::Bool:    [[fallthrough]];
479	            case Types::UInt64:  return get<UInt64>()  < rhs.get<UInt64>();
480	            case Types::UInt128: return get<UInt128>() < rhs.get<UInt128>();
481	            case Types::UInt256: return get<UInt256>() < rhs.get<UInt256>();
482	            case Types::Int64:   return get<Int64>()   < rhs.get<Int64>();
483	            case Types::Int128:  return get<Int128>()  < rhs.get<Int128>();
484	            case Types::Int256:  return get<Int256>()  < rhs.get<Int256>();
485	            case Types::UUID:    return get<UUID>()    < rhs.get<UUID>();
486	            case Types::Float64: return get<Float64>() < rhs.get<Float64>();
487	            case Types::String:  return get<String>()  < rhs.get<String>();
488	            case Types::Array:   return get<Array>()   < rhs.get<Array>();
489	            case Types::Tuple:   return get<Tuple>()   < rhs.get<Tuple>();
490	            case Types::Map:     return get<Map>()     < rhs.get<Map>();
491	            case Types::Object:  return get<Object>()  < rhs.get<Object>();
492	            case Types::Decimal32:  return get<DecimalField<Decimal32>>()  < rhs.get<DecimalField<Decimal32>>();
493	            case Types::Decimal64:  return get<DecimalField<Decimal64>>()  < rhs.get<DecimalField<Decimal64>>();
494	            case Types::Decimal128: return get<DecimalField<Decimal128>>() < rhs.get<DecimalField<Decimal128>>();
495	            case Types::Decimal256: return get<DecimalField<Decimal256>>() < rhs.get<DecimalField<Decimal256>>();
496	            case Types::AggregateFunctionState:  return get<AggregateFunctionStateData>() < rhs.get<AggregateFunctionStateData>();
497	        }
