546	    // More like bitwise equality as opposed to semantic equality:
547	    // Null equals Null and NaN equals NaN.
548	    bool operator== (const Field & rhs) const
549	    {
550	        if (which != rhs.which)
551	            return false;
552	
553	        switch (which)
554	        {
555	            case Types::Null: return true;
556	            case Types::Bool: [[fallthrough]];
557	            case Types::UInt64: return get<UInt64>() == rhs.get<UInt64>();
558	            case Types::Int64:   return get<Int64>() == rhs.get<Int64>();
559	            case Types::Float64:
560	            {
561	                // Compare as UInt64 so that NaNs compare as equal.
562	                return reinterpret<UInt64>() == rhs.reinterpret<UInt64>();
563	            }
564	            case Types::UUID:    return get<UUID>()    == rhs.get<UUID>();
565	            case Types::String:  return get<String>()  == rhs.get<String>();
566	            case Types::Array:   return get<Array>()   == rhs.get<Array>();
567	            case Types::Tuple:   return get<Tuple>()   == rhs.get<Tuple>();
568	            case Types::Map:     return get<Map>()     == rhs.get<Map>();
569	            case Types::Object:  return get<Object>()  == rhs.get<Object>();
570	            case Types::UInt128: return get<UInt128>() == rhs.get<UInt128>();
571	            case Types::UInt256: return get<UInt256>() == rhs.get<UInt256>();
572	            case Types::Int128:  return get<Int128>()  == rhs.get<Int128>();
573	            case Types::Int256:  return get<Int256>()  == rhs.get<Int256>();
574	            case Types::Decimal32:  return get<DecimalField<Decimal32>>()  == rhs.get<DecimalField<Decimal32>>();
575	            case Types::Decimal64:  return get<DecimalField<Decimal64>>()  == rhs.get<DecimalField<Decimal64>>();
