589	    /// Field is template parameter, to allow universal reference for field,
590	    /// that is useful for const and non-const .
591	    template <typename F, typename FieldRef>
592	    static auto dispatch(F && f, FieldRef && field)
593	    {
594	        switch (field.which)
595	        {
596	            case Types::Null:    return f(field.template get<Null>());
597	// gcc 8.2.1
598	#if !defined(__clang__)
599	#pragma GCC diagnostic push
600	#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
601	#endif
602	            case Types::UInt64:  return f(field.template get<UInt64>());
603	            case Types::UInt128: return f(field.template get<UInt128>());
604	            case Types::UInt256: return f(field.template get<UInt256>());
605	            case Types::Int64:   return f(field.template get<Int64>());
606	            case Types::Int128:  return f(field.template get<Int128>());
607	            case Types::Int256:  return f(field.template get<Int256>());
608	            case Types::UUID:    return f(field.template get<UUID>());
609	            case Types::Float64: return f(field.template get<Float64>());
610	            case Types::String:  return f(field.template get<String>());
611	            case Types::Array:   return f(field.template get<Array>());
612	            case Types::Tuple:   return f(field.template get<Tuple>());
613	            case Types::Map:     return f(field.template get<Map>());
614	            case Types::Bool:
615	            {
616	                bool value = bool(field.template get<UInt64>());
617	                return f(value);
618	            }
619	            case Types::Object:     return f(field.template get<Object>());
620	            case Types::Decimal32:  return f(field.template get<DecimalField<Decimal32>>());
621	            case Types::Decimal64:  return f(field.template get<DecimalField<Decimal64>>());
622	            case Types::Decimal128: return f(field.template get<DecimalField<Decimal128>>());
623	            case Types::Decimal256: return f(field.template get<DecimalField<Decimal256>>());
624	            case Types::AggregateFunctionState: return f(field.template get<AggregateFunctionStateData>());
625	#if !defined(__clang__)
626	#pragma GCC diagnostic pop
627	#endif
628	        }
629	
630	        __builtin_unreachable();
631	    }
