646	    /// Assuming there was no allocated state or it was deallocated (see destroy).
647	    template <typename T>
648	    void createConcrete(T && x)
649	    {
650	        using UnqualifiedType = std::decay_t<T>;
651	
652	        // In both Field and PODArray, small types may be stored as wider types,
653	        // e.g. char is stored as UInt64. Field can return this extended value
654	        // with get<StorageType>(). To avoid uninitialized results from get(),
655	        // we must initialize the entire wide stored type, and not just the
656	        // nominal type.
657	        using StorageType = NearestFieldType<UnqualifiedType>;
658	        new (&storage) StorageType(std::forward<T>(x));
659	        which = TypeToEnum<UnqualifiedType>::value;
660	    }
661	
662	    /// Assuming same types.
663	    template <typename T>
664	    void assignConcrete(T && x)
665	    {
666	        using JustT = std::decay_t<T>;
667	        assert(which == TypeToEnum<JustT>::value);
668	        JustT * MAY_ALIAS ptr = reinterpret_cast<JustT *>(&storage);
669	        *ptr = std::forward<T>(x);
670	    }
671	
672	    template <typename CharT>
673	    requires (sizeof(CharT) == 1)
674	    void assignString(const CharT * data, size_t size)
675	    {
676	        assert(which == Types::String);
677	        String * ptr = reinterpret_cast<String *>(&storage);
678	        ptr->assign(reinterpret_cast<const char *>(data), size);
679	    }
680	
681	    void assignString(String && str)
682	    {
683	        assert(which == Types::String);
684	        String * ptr = reinterpret_cast<String *>(&storage);
685	        ptr->assign(std::move(str));
686	    }
687	
688	    void create(const Field & x)
689	    {
690	        dispatch([this] (auto & value) { createConcrete(value); }, x);
691	    }
692	
693	    void create(Field && x)
694	    {
695	        dispatch([this] (auto & value) { createConcrete(std::move(value)); }, x);
696	    }
697	
698	    void assign(const Field & x)
699	    {
700	        dispatch([this] (auto & value) { assignConcrete(value); }, x);
701	    }
702	
703	    void assign(Field && x)
704	    {
705	        dispatch([this] (auto & value) { assignConcrete(std::move(value)); }, x);
706	    }
