708	    template <typename CharT>
709	    requires (sizeof(CharT) == 1)
710	    void create(const CharT * data, size_t size)
711	    {
712	        new (&storage) String(reinterpret_cast<const char *>(data), size);
713	        which = Types::String;
714	    }
715	
716	    void create(String && str)
717	    {
718	        new (&storage) String(std::move(str));
719	        which = Types::String;
720	    }
