722	    ALWAYS_INLINE void destroy()
723	    {
724	        switch (which)
725	        {
726	            case Types::String:
727	                destroy<String>();
728	                break;
729	            case Types::Array:
730	                destroy<Array>();
731	                break;
732	            case Types::Tuple:
733	                destroy<Tuple>();
734	                break;
735	            case Types::Map:
736	                destroy<Map>();
737	                break;
738	            case Types::Object:
739	                destroy<Object>();
740	                break;
741	            case Types::AggregateFunctionState:
742	                destroy<AggregateFunctionStateData>();
743	                break;
744	            default:
745	                 break;
746	        }
747	
748	        which = Types::Null;    /// for exception safety in subsequent calls to destroy and create, when create fails.
749	    }
750	
751	    template <typename T>
752	    void destroy()
753	    {
754	        T * MAY_ALIAS ptr = reinterpret_cast<T*>(&storage);
755	        ptr->~T();
756	    }
