821	// Field value getter with type checking in debug builds.
822	template <typename T>
823	NearestFieldType<std::decay_t<T>> & Field::get()
824	{
825	    // Before storing the value in the Field, we static_cast it to the field
826	    // storage type, so here we return the value of storage type as well.
827	    // Otherwise, it is easy to make a mistake of reinterpret_casting the stored
828	    // value to a different and incompatible type.
829	    // For example, a Float32 value is stored as Float64, and it is incorrect to
830	    // return a reference to this value as Float32.
831	    using StoredType = NearestFieldType<std::decay_t<T>>;
832	
833	#ifndef NDEBUG
834	    // Disregard signedness when converting between int64 types.
835	    constexpr Field::Types::Which target = TypeToEnum<StoredType>::value;
836	    if (target != which
837	           && (!isInt64OrUInt64orBoolFieldType(target) || !isInt64OrUInt64orBoolFieldType(which)))
838	        throw Exception(ErrorCodes::LOGICAL_ERROR,
839	            "Invalid Field get from type {} to type {}", which, target);
840	#endif
841	
842	    StoredType * MAY_ALIAS ptr = reinterpret_cast<StoredType *>(&storage);
843	
844	    return *ptr;
845	}
