58	void LRUFileCache::useCell(
59	    const FileSegmentCell & cell, FileSegments & result, std::lock_guard<std::mutex> & cache_lock)
60	{
61	    auto file_segment = cell.file_segment;
62	
63	    if (file_segment->isDownloaded()
64	        && fs::file_size(getPathInLocalCache(file_segment->key(), file_segment->offset(), file_segment->isPersistent())) == 0)
65	        throw Exception(ErrorCodes::LOGICAL_ERROR,
66	                        "Cannot have zero size downloaded file segments. Current file segment: {}",
67	                        file_segment->range().toString());
68	
69	    result.push_back(cell.file_segment);
70	
71	    /**
72	     * A cell receives a queue iterator on first successful space reservation attempt
73	     * (space is reserved incrementally on each read buffer nextImpl() call).
74	     */
75	    if (cell.queue_iterator)
76	    {
77	        /// Move to the end of the queue. The iterator remains valid.
78	        queue.moveToEnd(*cell.queue_iterator, cache_lock);
79	    }
80	}
