82	LRUFileCache::FileSegmentCell * LRUFileCache::getCell(
83	    const Key & key, size_t offset, std::lock_guard<std::mutex> & /* cache_lock */)
84	{
85	    auto it = files.find(key);
86	    if (it == files.end())
87	        return nullptr;
88	
89	    auto & offsets = it->second;
90	    auto cell_it = offsets.find(offset);
91	    if (cell_it == offsets.end())
92	        return nullptr;
93	
94	    return &cell_it->second;
95	}
