133	void IFileCache::QueryContext::remove(const Key & key, size_t offset, size_t size, std::lock_guard<std::mutex> & cache_lock)
134	{
135	    if (cache_size < size)
136	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Deleted cache size exceeds existing cache size");
137	
138	    if (!skip_download_if_exceeds_query_cache)
139	    {
140	        auto record = records.find({key, offset});
141	        if (record != records.end())
142	        {
143	            lru_queue.remove(record->second, cache_lock);
144	            records.erase({key, offset});
145	        }
146	    }
147	    cache_size -= size;
148	}
149	
150	void IFileCache::QueryContext::reserve(const Key & key, size_t offset, size_t size, std::lock_guard<std::mutex> & cache_lock)
151	{
152	    if (cache_size + size > max_cache_size)
153	    {
154	        throw Exception(
155	            ErrorCodes::LOGICAL_ERROR,
156	            "Reserved cache size exceeds the remaining cache size (key: {}, offset: {})",
157	            key.toString(), offset);
158	    }
159	
160	    if (!skip_download_if_exceeds_query_cache)
161	    {
162	        auto record = records.find({key, offset});
163	        if (record == records.end())
164	        {
165	            auto queue_iter = lru_queue.add(key, offset, 0, cache_lock);
166	            record = records.insert({{key, offset}, queue_iter}).first;
167	        }
168	        record->second->size += size;
169	    }
170	    cache_size += size;
171	}
172	
173	void IFileCache::QueryContext::use(const Key & key, size_t offset, std::lock_guard<std::mutex> & cache_lock)
174	{
175	    if (skip_download_if_exceeds_query_cache)
176	        return;
177	
178	    auto record = records.find({key, offset});
179	    if (record != records.end())
180	        lru_queue.moveToEnd(record->second, cache_lock);
181	}
