361	LRUFileCache::FileSegmentCell * LRUFileCache::addCell(
362	    const Key & key, size_t offset, size_t size,
363	    FileSegment::State state, bool is_persistent,
364	    std::lock_guard<std::mutex> & cache_lock)
365	{
366	    /// Create a file segment cell and put it in `files` map by [key][offset].
367	
368	    if (!size)
369	        return nullptr; /// Empty files are not cached.
370	
371	    if (files[key].contains(offset))
372	        throw Exception(
373	            ErrorCodes::LOGICAL_ERROR,
374	            "Cache already exists for key: `{}`, offset: {}, size: {}.\nCurrent cache structure: {}",
375	            key.toString(), offset, size, dumpStructureUnlocked(key, cache_lock));
376	
377	    auto skip_or_download = [&]() -> FileSegmentPtr
378	    {
379	        FileSegment::State result_state = state;
380	        if (state == FileSegment::State::EMPTY && enable_cache_hits_threshold)
381	        {
382	            auto record = records.find({key, offset});
383	
384	            if (record == records.end())
385	            {
386	                auto queue_iter = stash_queue.add(key, offset, 0, cache_lock);
387	                records.insert({{key, offset}, queue_iter});
388	
389	                if (stash_queue.getElementsNum(cache_lock) > max_stash_element_size)
390	                {
391	                    auto remove_queue_iter = stash_queue.begin();
392	                    records.erase({remove_queue_iter->key, remove_queue_iter->offset});
393	                    stash_queue.remove(remove_queue_iter, cache_lock);
394	                }
395	
396	                /// For segments that do not reach the download threshold, we do not download them, but directly read them
397	                result_state = FileSegment::State::SKIP_CACHE;
398	            }
399	            else
400	            {
401	                auto queue_iter = record->second;
402	                queue_iter->hits++;
403	                stash_queue.moveToEnd(queue_iter, cache_lock);
404	
405	                result_state = queue_iter->hits >= enable_cache_hits_threshold ? FileSegment::State::EMPTY : FileSegment::State::SKIP_CACHE;
406	            }
407	        }
408	
409	        return std::make_shared<FileSegment>(offset, size, key, this, result_state, is_persistent);
410	    };
411	
412	    FileSegmentCell cell(skip_or_download(), this, cache_lock);
413	    auto & offsets = files[key];
414	
415	    if (offsets.empty())
416	    {
417	        auto key_path = getPathInLocalCache(key);
418	        if (!fs::exists(key_path))
419	            fs::create_directories(key_path);
420	    }
421	
422	    auto [it, inserted] = offsets.insert({offset, std::move(cell)});
423	    if (!inserted)
424	        throw Exception(
425	            ErrorCodes::LOGICAL_ERROR,
426	            "Failed to insert into cache key: `{}`, offset: {}, size: {}",
427	            key.toString(), offset, size);
428	
429	    return &(it->second);
430	}
