26	                || path.ends_with("mrk") || path.ends_with("mrk2") || path.ends_with("mrk3") /// mark files.
27	                || path.ends_with("txt") || path.ends_with("dat");
28	    };
29	
30	    return std::make_shared<DiskCacheWrapper>(disk, cache_disk, cache_file_predicate);
