587	    /// A cell acquires a LRUQueue iterator on first successful space reservation attempt.
588	    /// cell_for_reserve can be nullptr here when we call tryReserve() from loadCacheInfoIntoMemory().
589	    if (!cell_for_reserve || !cell_for_reserve->queue_iterator)
