613	
614	        size_t cell_size = cell->size();
615	        assert(entry_size == cell_size);
616	
617	        /// It is guaranteed that cell is not removed from cache as long as
618	        /// pointer to corresponding file segment is hold by any other thread.
619	
620	        if (cell->releasable())
