834	void LRUFileCache::loadCacheInfoIntoMemory(std::lock_guard<std::mutex> & cache_lock)
835	{
836	    Key key;
837	    UInt64 offset = 0;
838	    size_t size = 0;
839	    std::vector<std::pair<LRUQueue::Iterator, std::weak_ptr<FileSegment>>> queue_entries;
840	
841	    /// cache_base_path / key_prefix / key / offset
842	
843	    if (!files.empty())
844	        throw Exception(
845	            ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
846	            "Cache initialization is partially made. "
847	            "This can be a result of a failed first attempt to initialize cache. "
848	            "Please, check log for error messages");
849	
850	    fs::directory_iterator key_prefix_it{cache_base_path};
851	    for (; key_prefix_it != fs::directory_iterator(); ++key_prefix_it)
852	    {
853	        fs::directory_iterator key_it{key_prefix_it->path()};
854	        for (; key_it != fs::directory_iterator(); ++key_it)
855	        {
856	            key = Key(unhexUInt<UInt128>(key_it->path().filename().string().data()));
857	
858	            fs::directory_iterator offset_it{key_it->path()};
859	            for (; offset_it != fs::directory_iterator(); ++offset_it)
860	            {
861	                auto offset_with_suffix = offset_it->path().filename().string();
862	                auto delim_pos = offset_with_suffix.find('_');
863	                bool parsed;
864	                bool is_persistent = false;
865	
866	                if (delim_pos == std::string::npos)
867	                    parsed = tryParse<UInt64>(offset, offset_with_suffix);
868	                else
869	                {
870	                    parsed = tryParse<UInt64>(offset, offset_with_suffix.substr(0, delim_pos));
871	                    is_persistent = offset_with_suffix.substr(delim_pos+1) == "persistent";
872	                }
873	
874	                if (!parsed)
875	                {
876	                    LOG_WARNING(log, "Unexpected file: ", offset_it->path().string());
877	                    continue; /// Or just remove? Some unexpected file.
878	                }
879	
880	                size = offset_it->file_size();
881	                if (!size)
882	                {
883	                    fs::remove(offset_it->path());
884	                    continue;
885	                }
886	
887	                if (tryReserve(key, offset, size, cache_lock))
888	                {
889	                    auto * cell = addCell(key, offset, size, FileSegment::State::DOWNLOADED, is_persistent, cache_lock);
890	                    if (cell)
891	                        queue_entries.emplace_back(*cell->queue_iterator, cell->file_segment);
892	                }
893	                else
894	                {
895	                    LOG_WARNING(log,
896	                                "Cache capacity changed (max size: {}, available: {}), cached file `{}` does not fit in cache anymore (size: {})",
897	                                max_size, getAvailableCacheSizeUnlocked(cache_lock), key_it->path().string(), size);
898	                    fs::remove(offset_it->path());
899	                }
900	            }
901	        }
902	    }
903	
904	    /// Shuffle cells to have random order in LRUQueue as at startup all cells have the same priority.
905	    pcg64 generator(randomSeed());
906	    std::shuffle(queue_entries.begin(), queue_entries.end(), generator);
907	    for (const auto & [it, file_segment] : queue_entries)
908	    {
909	        /// Cell cache size changed and, for example, 1st file segment fits into cache
910	        /// and 2nd file segment will fit only if first was evicted, then first will be removed and
911	        /// cell is nullptr here.
912	        if (file_segment.expired())
913	            continue;
914	
915	        queue.moveToEnd(it, cache_lock);
916	    }
917	#ifndef NDEBUG
918	    assertCacheCorrectness(cache_lock);
919	#endif
920	}
