922	void LRUFileCache::reduceSizeToDownloaded(
923	    const Key & key, size_t offset,
924	    std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & /* segment_lock */)
925	{
926	    /**
927	     * In case file was partially downloaded and it's download cannot be continued
928	     * because of no space left in cache, we need to be able to cut cell's size to downloaded_size.
929	     */
930	
931	    auto * cell = getCell(key, offset, cache_lock);
932	
933	    if (!cell)
934	    {
935	        throw Exception(
936	            ErrorCodes::LOGICAL_ERROR,
937	            "No cell found for key: {}, offset: {}",
938	            key.toString(), offset);
939	    }
940	
941	    const auto & file_segment = cell->file_segment;
942	
943	    size_t downloaded_size = file_segment->downloaded_size;
944	    if (downloaded_size == file_segment->range().size())
945	    {
946	        throw Exception(
947	            ErrorCodes::LOGICAL_ERROR,
948	            "Nothing to reduce, file segment fully downloaded, key: {}, offset: {}",
949	            key.toString(), offset);
950	    }
951	
952	    cell->file_segment = std::make_shared<FileSegment>(offset, downloaded_size, key, this, FileSegment::State::DOWNLOADED);
953	}
