962	        throw Exception(ErrorCodes::LOGICAL_ERROR, "No cell found for key: {}, offset: {}", key.toString(), offset);
963	
964	    /// The caller of this method is last file segment holder if use count is 2 (the second pointer is cache itself)
965	    return cell->file_segment.use_count() == 2;
