22	inline Field getBinaryValue(UInt8 type, ReadBuffer & buf)
23	{
24	    switch (type)
25	    {
26	        case Field::Types::Null:
27	        {
28	            return Field();
29	        }
30	        case Field::Types::UInt64:
31	        {
32	            UInt64 value;
33	            readVarUInt(value, buf);
34	            return value;
35	        }
36	        case Field::Types::UInt128:
37	        {
38	            UInt128 value;
39	            readBinary(value, buf);
40	            return value;
41	        }
42	        case Field::Types::UInt256:
43	        {
44	            UInt256 value;
45	            readBinary(value, buf);
46	            return value;
47	        }
48	        case Field::Types::UUID:
49	        {
50	            UUID value;
51	            readBinary(value, buf);
52	            return value;
53	        }
54	        case Field::Types::Int64:
55	        {
56	            Int64 value;
57	            readVarInt(value, buf);
58	            return value;
59	        }
60	        case Field::Types::Int128:
61	        {
62	            Int128 value;
63	            readBinary(value, buf);
64	            return value;
65	        }
66	        case Field::Types::Int256:
67	        {
68	            Int256 value;
69	            readBinary(value, buf);
70	            return value;
71	        }
72	        case Field::Types::Float64:
73	        {
74	            Float64 value;
75	            readFloatBinary(value, buf);
76	            return value;
77	        }
78	        case Field::Types::String:
79	        {
80	            std::string value;
81	            readStringBinary(value, buf);
82	            return value;
83	        }
84	        case Field::Types::Array:
85	        {
86	            Array value;
87	            readBinary(value, buf);
88	            return value;
89	        }
90	        case Field::Types::Tuple:
91	        {
92	            Tuple value;
93	            readBinary(value, buf);
94	            return value;
95	        }
96	        case Field::Types::Map:
97	        {
98	            Map value;
99	            readBinary(value, buf);
100	            return value;
101	        }
102	        case Field::Types::Object:
103	        {
104	            Object value;
105	            readBinary(value, buf);
106	            return value;
107	        }
108	        case Field::Types::AggregateFunctionState:
109	        {
110	            AggregateFunctionStateData value;
111	            readStringBinary(value.name, buf);
112	            readStringBinary(value.data, buf);
113	            return value;
114	        }
115	        case Field::Types::Bool:
116	        {
117	            UInt8 value;
118	            readBinary(value, buf);
119	            return bool(value);
120	        }
121	    }
122	    return Field();
123	}
