251	template <typename T>
252	void readQuoted(DecimalField<T> & x, ReadBuffer & buf)
253	{
254	    assertChar('\'', buf);
255	    T value;
256	    UInt32 scale;
257	    int32_t exponent;
258	    uint32_t max_digits = static_cast<uint32_t>(-1);
259	    readDigits<true>(buf, value, max_digits, exponent, true);
260	    if (exponent > 0)
261	    {
262	        scale = 0;
263	        if (common::mulOverflow(value.value, DecimalUtils::scaleMultiplier<T>(exponent), value.value))
264	            throw Exception("Decimal math overflow", ErrorCodes::DECIMAL_OVERFLOW);
265	    }
266	    else
267	        scale = -exponent;
268	    assertChar('\'', buf);
269	    x = DecimalField<T>{value, scale};
270	}
