289	Field Field::restoreFromDump(std::string_view dump_)
290	{
291	    auto show_error = [&dump_]
292	    {
293	        throw Exception("Couldn't restore Field from dump: " + String{dump_}, ErrorCodes::CANNOT_RESTORE_FROM_FIELD_DUMP);
294	    };
295	
296	    std::string_view dump = dump_;
297	    trim(dump);
298	
299	    if (dump == "NULL")
300	        return {};
301	
302	    std::string_view prefix = std::string_view{"Int64_"};
303	    if (dump.starts_with(prefix))
304	    {
305	        Int64 value = parseFromString<Int64>(dump.substr(prefix.length()));
306	        return value;
307	    }
308	
309	    prefix = std::string_view{"UInt64_"};
310	    if (dump.starts_with(prefix))
311	    {
312	        UInt64 value = parseFromString<UInt64>(dump.substr(prefix.length()));
313	        return value;
314	    }
315	
316	    prefix = std::string_view{"Int128_"};
317	    if (dump.starts_with(prefix))
318	    {
319	        Int128 value = parseFromString<Int128>(dump.substr(prefix.length()));
320	        return value;
321	    }
322	
323	    prefix = std::string_view{"UInt128_"};
324	    if (dump.starts_with(prefix))
325	    {
326	        UInt128 value = parseFromString<UInt128>(dump.substr(prefix.length()));
327	        return value;
328	    }
329	
330	    prefix = std::string_view{"Int256_"};
331	    if (dump.starts_with(prefix))
332	    {
333	        Int256 value = parseFromString<Int256>(dump.substr(prefix.length()));
334	        return value;
335	    }
336	
337	    prefix = std::string_view{"UInt256_"};
338	    if (dump.starts_with(prefix))
339	    {
340	        UInt256 value = parseFromString<UInt256>(dump.substr(prefix.length()));
341	        return value;
342	    }
343	
344	    prefix = std::string_view{"Float64_"};
345	    if (dump.starts_with(prefix))
346	    {
347	        Float64 value = parseFromString<Float64>(dump.substr(prefix.length()));
348	        return value;
349	    }
350	
351	    prefix = std::string_view{"Decimal32_"};
352	    if (dump_.starts_with(prefix))
353	    {
354	        DecimalField<Decimal32> decimal;
355	        ReadBufferFromString buf{dump.substr(prefix.length())};
356	        readQuoted(decimal, buf);
357	        return decimal;
358	    }
359	
360	    prefix = std::string_view{"Decimal64_"};
361	    if (dump_.starts_with(prefix))
362	    {
363	        DecimalField<Decimal64> decimal;
364	        ReadBufferFromString buf{dump.substr(prefix.length())};
365	        readQuoted(decimal, buf);
366	        return decimal;
367	    }
368	
369	    prefix = std::string_view{"Decimal128_"};
370	    if (dump_.starts_with(prefix))
371	    {
372	        DecimalField<Decimal128> decimal;
373	        ReadBufferFromString buf{dump.substr(prefix.length())};
374	        readQuoted(decimal, buf);
375	        return decimal;
376	    }
377	
378	    prefix = std::string_view{"Decimal256_"};
379	    if (dump_.starts_with(prefix))
380	    {
381	        DecimalField<Decimal256> decimal;
382	        ReadBufferFromString buf{dump.substr(prefix.length())};
383	        readQuoted(decimal, buf);
384	        return decimal;
385	    }
386	
387	    if (dump.starts_with("\'"))
388	    {
389	        String str;
390	        ReadBufferFromString buf{dump};
391	        readQuoted(str, buf);
392	        return str;
393	    }
394	
395	    prefix = std::string_view{"Bool_"};
396	    if (dump.starts_with(prefix))
397	    {
398	        bool value = parseFromString<bool>(dump.substr(prefix.length()));
399	        return value;
400	    }
401	
402	    prefix = std::string_view{"Array_["};
403	    if (dump.starts_with(prefix))
404	    {
405	        std::string_view tail = dump.substr(prefix.length());
406	        trimLeft(tail);
407	        Array array;
408	        while (tail != "]")
409	        {
410	            size_t separator = tail.find_first_of(",]");
411	            if (separator == std::string_view::npos)
412	                show_error();
413	            bool comma = (tail[separator] == ',');
414	            std::string_view element = tail.substr(0, separator);
415	            tail.remove_prefix(separator);
416	            if (comma)
417	                tail.remove_prefix(1);
418	            trimLeft(tail);
419	            if (!comma && tail != "]")
420	                show_error();
421	            array.push_back(Field::restoreFromDump(element));
422	        }
423	        return array;
424	    }
425	
426	    prefix = std::string_view{"Tuple_("};
427	    if (dump.starts_with(prefix))
428	    {
429	        std::string_view tail = dump.substr(prefix.length());
430	        trimLeft(tail);
431	        Tuple tuple;
432	        while (tail != ")")
433	        {
434	            size_t separator = tail.find_first_of(",)");
435	            if (separator == std::string_view::npos)
436	                show_error();
437	            bool comma = (tail[separator] == ',');
438	            std::string_view element = tail.substr(0, separator);
439	            tail.remove_prefix(separator);
440	            if (comma)
441	                tail.remove_prefix(1);
442	            trimLeft(tail);
443	            if (!comma && tail != ")")
444	                show_error();
445	            tuple.push_back(Field::restoreFromDump(element));
446	        }
447	        return tuple;
448	    }
449	
450	    prefix = std::string_view{"Map_("};
451	    if (dump.starts_with(prefix))
452	    {
453	        std::string_view tail = dump.substr(prefix.length());
454	        trimLeft(tail);
455	        Map map;
456	        while (tail != ")")
457	        {
458	            size_t separator = tail.find_first_of(",)");
459	            if (separator == std::string_view::npos)
460	                show_error();
461	            bool comma = (tail[separator] == ',');
462	            std::string_view element = tail.substr(0, separator);
463	            tail.remove_prefix(separator);
464	            if (comma)
465	                tail.remove_prefix(1);
466	            trimLeft(tail);
467	            if (!comma && tail != ")")
468	                show_error();
469	            map.push_back(Field::restoreFromDump(element));
470	        }
471	        return map;
472	    }
473	
474	    prefix = std::string_view{"AggregateFunctionState_("};
475	    if (dump.starts_with(prefix))
476	    {
477	        std::string_view after_prefix = dump.substr(prefix.length());
478	        size_t comma = after_prefix.find(',');
479	        size_t end = after_prefix.find(')', comma + 1);
480	        if ((comma == std::string_view::npos) || (end != after_prefix.length() - 1))
481	            show_error();
482	        std::string_view name_view = after_prefix.substr(0, comma);
483	        std::string_view data_view = after_prefix.substr(comma + 1, end - comma - 1);
484	        trim(name_view);
485	        trim(data_view);
486	        ReadBufferFromString name_buf{name_view};
487	        ReadBufferFromString data_buf{data_view};
488	        AggregateFunctionStateData res;
489	        readQuotedString(res.name, name_buf);
490	        readQuotedString(res.data, data_buf);
491	        return res;
492	    }
493	
494	    show_error();
495	    __builtin_unreachable();
496	}
